export const colours={JavaScript:'#dfb44f',TypeScript:'#758fc1',Python:'#b099cd',Rust:'#dc896d',Go:'#72b8b8',HTML:'#e79592',CSS:'#b68abd',Java:'#bd9269',Ruby:'#dc7280',C:'#95a9b5',Unknown:'#b8bf8d'};
export function growth(repo,now=Date.now()){const age=Math.max(0,(now-Date.parse(repo.created_at))/86400000);return age<30?0:age<180?1:2;}
export function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function selectRepos(repos,filter,sort){return repos.filter(r=>filter==='all'||(filter==='forks'?r.fork:!r.fork)).sort((a,b)=>sort==='stars'?b.stargazers_count-a.stargazers_count:sort==='name'?a.name.localeCompare(b.name):Date.parse(b.updated_at)-Date.parse(a.updated_at));}
export function plantSVG(repo){const stage=growth(repo),colour=colours[repo.language]||colours.Unknown,top=[110,78,43][stage],stars=Math.min(5,Math.ceil(Math.log2((repo.stargazers_count||0)+1))),leaf=(x,y,flip=false)=>`<path d="M ${x} ${y} q ${flip?-42:42} -37 ${flip?-47:47} -10 q ${flip?20:-20} 26 ${flip?47:-47} 10" fill="${flip?'#779960':'#91ad75'}"/><path d="M${x} ${y} l${flip?-35:35} -14" stroke="#5c824f" fill="none" stroke-width="1"/>`;let blooms='';for(let i=0;i<stars;i++){let x=100+(i%2?-1:1)*(i?28+i*5:0),y=top+8+i*16;blooms+=`<g transform="translate(${x} ${y})"><path d="M0 4 Q${(100-x)/2} 35 ${100-x} ${155-y}" fill="none" stroke="#63844e" stroke-width="2"/>${[0,60,120,180,240,300].map(a=>`<ellipse cy="-8" rx="6" ry="10" fill="${colour}" transform="rotate(${a})"/>`).join('')}<circle r="5" fill="#f3d681"/></g>`;}return `<svg viewBox="0 0 200 200" aria-hidden="true"><ellipse cx="100" cy="181" rx="44" ry="7" fill="#66734516"/><g class="sway"><path d="M100 175 Q90 120 100 ${top}" fill="none" stroke="#628250" stroke-width="5" stroke-linecap="round"/>${leaf(97,141)}${stage>0?leaf(98,115,true):''}${stage>1?leaf(99,88):''}${blooms||`<ellipse cx="100" cy="${top}" rx="7" ry="12" fill="${colour}"/>`}</g><path d="M77 165 L123 165 L117 190 Q100 196 83 190Z" fill="${repo.fork?'#a9b19b':'#c58f70'}"/><path d="M74 163 h52 v9 H74Z" fill="${repo.fork?'#bbc2ad':'#d9a68a'}"/><path d="M86 175 v10" stroke="#ffffff33" stroke-width="3" stroke-linecap="round"/>${repo.open_issues_count>0?'<g transform="translate(146 151)"><path d="M-6 0h-4m16 0h4m-16-4-3-3m15 3 3-3" stroke="#786c48"/><ellipse rx="6" ry="8" fill="#a49864"/><path d="M0-7v14" stroke="#786c48"/></g>':''}</svg>`;}
